const dialog=document.querySelector('dialog'),track=document.querySelector('#track'),saved=document.querySelector('#saved');
document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>{track.value=b.dataset.track;saved.textContent='';dialog.showModal()});document.querySelector('.close').onclick=()=>dialog.close();document.querySelector('form').onsubmit=e=>{e.preventDefault();localStorage.setItem('astra-focus',track.value);saved.textContent=`Your starting point: ${track.value}. Saved on this device.`};
// Character motion is driven by viewport progress; artwork stays readable at rest.
const media=matchMedia('(prefers-reduced-motion: reduce)');let motion=!media.matches;
const fight=document.querySelector('.art-versus');fight.classList.add('fight-stage');fight.innerHTML='<div class="fight-team team-strength" aria-hidden="true"></div><div class="fight-team team-strategy" aria-hidden="true"></div>';
const clamp=v=>Math.max(0,Math.min(1,v));
const items=[...document.querySelectorAll('.scene')].map((scene,i)=>({scene,art:scene.querySelector('.art'),i,p:0,target:0,visible:false,px:0,py:0,tx:0,ty:0}));
let frameId=0,lastTime=0;
function measure(){items.forEach(item=>{const r=item.art.getBoundingClientRect(),sr=item.scene.getBoundingClientRect();item.visible=sr.bottom>0&&sr.top<innerHeight;item.target=clamp((innerHeight-r.top)/(Math.min(innerHeight,r.height)*.7));});wake()}
function reset(){items.forEach(item=>{item.art.style.transform='none';item.art.style.opacity='1';item.art.querySelectorAll('.fight-team').forEach(el=>{el.style.transform='none';el.style.opacity='1'})});document.querySelectorAll('.copy,.versus-copy').forEach(el=>{el.style.opacity='1';el.style.transform='none'})}
function tick(time){frameId=0;if(!motion||document.hidden){reset();return}const dt=Math.min(40,time-lastTime||16);lastTime=time;const smoothing=1-Math.exp(-dt/110);let visible=false;items.forEach(item=>{if(!item.visible)return;visible=true;item.p+=(item.target-item.p)*smoothing;item.px+=(item.tx-item.px)*smoothing;item.py+=(item.ty-item.py)*smoothing;const p=clamp(item.p),ease=1-Math.pow(1-p,3),rest=clamp((p-.7)/.3),breath=Math.sin(time*.0015+item.i)*2*rest;if(item.art===fight){const offset=(1-ease)*110;const lean=(1-ease)*5;const left=item.art.querySelector('.team-strength'),right=item.art.querySelector('.team-strategy');left.style.transform=`translate3d(${-offset}px,${(1-ease)*28+breath}px,0) rotate(${-lean+.7*rest}px)`;right.style.transform=`translate3d(${offset}px,${(1-ease)*28-breath}px,0) rotate(${lean-.7*rest}deg)`;left.style.transform=`translate3d(${-offset}px,${(1-ease)*28+breath}px,0) rotate(${-lean+.7*rest}deg)`;left.style.opacity=right.style.opacity=.25+.75*ease;}else{const direction=item.i===0?1:-1;item.art.style.opacity=.2+.8*ease;item.art.style.transform=`translate3d(${direction*(1-ease)*75+item.px}px,${(1-ease)*40+breath+item.py}px,0) rotate(${direction*(1-ease)*2}deg) scale(${.96+.04*ease})`;}});if(visible)frameId=requestAnimationFrame(tick)}
function wake(){if(motion&&!frameId)frameId=requestAnimationFrame(tick)}
items.forEach(item=>{item.scene.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse'||!motion)return;const r=item.scene.getBoundingClientRect();item.tx=((e.clientX-r.left)/r.width-.5)*8;item.ty=((e.clientY-r.top)/r.height-.5)*5;wake()});item.scene.addEventListener('pointerleave',()=>{item.tx=item.ty=0;wake()})});
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){if(motion)anime.animate(e.target,{opacity:[0,1],y:[18,0],duration:850,ease:'outCubic'});observer.unobserve(e.target)}}),{threshold:.2});document.querySelectorAll('.copy,.versus-copy').forEach(e=>observer.observe(e));
function setMotion(enabled){motion=enabled;document.body.classList.toggle('still',!motion);document.querySelector('#motion').textContent='Motion '+(motion?'on':'off');if(!motion){cancelAnimationFrame(frameId);frameId=0;reset()}else measure()}
document.querySelector('#motion').onclick=()=>setMotion(!motion);media.addEventListener('change',e=>setMotion(!e.matches));document.addEventListener('visibilitychange',()=>{if(!document.hidden)measure()});window.addEventListener('scroll',measure,{passive:true});window.addEventListener('resize',measure);setMotion(motion);
